package eu.kanade.presentation.theme.colorscheme

import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.ui.graphics.Color

/**
 * Colors for Doom theme, from Aniyomi via Komikku (Apache 2.0)
 * Original color scheme by LuftVerbot; the light scheme and bottom bar colors are Reikai's
 * M3 colors generated by Material Theme Builder (https://goo.gle/material-theme-builder-web)
 *
 * Key colors: primary 0xFFFF0000, secondary 0xFFFF0000, tertiary 0xFFBFBFBF
 */
internal object DoomColorScheme : BaseColorScheme() {

    override val darkScheme = darkColorScheme(
        primary = Color(0xFFFF0000),
        onPrimary = Color(0xFFFAFAFA),
        primaryContainer = Color(0xFFFF0000),
        onPrimaryContainer = Color(0xFFFAFAFA),
        secondary = Color(0xFFFF0000),
        onSecondary = Color(0xFFFAFAFA),
        secondaryContainer = Color(0xFFFF0000),
        onSecondaryContainer = Color(0xFFFAFAFA),
        tertiary = Color(0xFFBFBFBF),
        onTertiary = Color(0xFFFF0000),
        tertiaryContainer = Color(0xFFBFBFBF),
        onTertiaryContainer = Color(0xFFFF0000),
        background = Color(0xFF1B1B1B),
        onBackground = Color(0xFFFFFFFF),
        surface = Color(0xFF1B1B1B),
        onSurface = Color(0xFFFFFFFF),
        surfaceVariant = Color(0xFF303030),
        onSurfaceVariant = Color(0xFFD8FFFFFF),
        surfaceTint = Color(0xFFFF0000),
        inverseSurface = Color(0xFFFAFAFA),
        inverseOnSurface = Color(0xFF313131),
        outline = Color(0xFFFF0000),
        inversePrimary = Color(0xFF6D0D0B),
        surfaceContainerLowest = Color(0xFF171717),
        surfaceContainerLow = Color(0xFF1F1F1F),
        surfaceContainer = Color(0xFF232323), // Navigation bar background
        surfaceContainerHigh = Color(0xFF292929),
        surfaceContainerHighest = Color(0xFF303030),
    )

    override val lightScheme = lightColorScheme(
        primary = Color(0xFFD50000),
        onPrimary = Color(0xFFFFFFFF),
        primaryContainer = Color(0xFFD50000),
        onPrimaryContainer = Color(0xFFFFFFFF),
        inversePrimary = Color(0xFFFF5252),
        secondary = Color(0xFFD50000), // Unread badge
        onSecondary = Color(0xFFFFFFFF), // Unread badge text
        secondaryContainer = Color(0xFFD50000), // Navigation bar selector pill & progress indicator (remaining)
        onSecondaryContainer = Color(0xFFFFFFFF), // Navigation bar selector icon
        tertiary = Color(0xFF616161), // Downloaded badge
        onTertiary = Color(0xFFFFFFFF), // Downloaded badge text
        tertiaryContainer = Color(0xFFE0E0E0),
        onTertiaryContainer = Color(0xFF1B1B1B),
        background = Color(0xFFFAFAFA),
        onBackground = Color(0xFF1B1B1B),
        surface = Color(0xFFFAFAFA),
        onSurface = Color(0xFF1B1B1B),
        surfaceVariant = Color(0xFFE0E0E0), // Navigation bar background (ThemePrefWidget)
        onSurfaceVariant = Color(0xFF5F5F5F),
        surfaceTint = Color(0xFFD50000),
        inverseSurface = Color(0xFF2B2B2B),
        inverseOnSurface = Color(0xFFF5F5F5),
        outline = Color(0xFFD50000),
        surfaceContainerLowest = Color(0xFFFFFFFF),
        surfaceContainerLow = Color(0xFFF5F5F5),
        surfaceContainer = Color(0xFFEEEEEE), // Navigation bar background
        surfaceContainerHigh = Color(0xFFE8E8E8),
        surfaceContainerHighest = Color(0xFFE2E2E2),
    )
}
